                centers.append((r, c))

    for r, c in centers:
        row_strength = sum(v == 2 for v in grid[r])
        col_strength = sum(grid[rr][c] == 2 for rr in range(h))
        vertical_barrier = col_strength >= row_strength
        if vertical_barrier:
            # A vertical barrier launches a horizontal beam.
            for cc in range(w):
                if g[r][cc] == 0:
