            barrier_indices = [cc for cc in range(w)
                               if sum(grid[rr][cc] == 2 for rr in range(h)) >= h / 2]
            targets = [cc for cc in barrier_indices if cc != c]
            for tc in targets:
                for rr in (r-1, r+1):
                    if 0 <= rr < h:
                        for cc in (tc-1, tc, tc+1):
                            if 0 <= cc < w and (rr, cc) != (r, c):
                                g[rr][cc] = 1
                for cc in (tc-1, tc+1):
