            for tr in targets:
                for rr in (tr-1, tr+1):
                    if 0 <= rr < h:
                        for cc in (c-1, c, c+1):
                            if 0 <= cc < w:
                                g[rr][cc] = 1
                for rr in (tr-1, tr+1):
                    pass
                for cc in (c-1, c+1):
                    if 0 <= cc < w:
                        g[tr][cc] = 1
    return g
